(function() {
    'use strict';

    class BoardGovernanceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Board Effectiveness: Governance in the Boardroom';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    briefingKey: 'r1_brief',
                    optionKeys: ['r1_opt1', 'r1_opt2', 'r1_opt3', 'r1_opt4'],
                    scores: [
                        { procedural: 0, substantive: 1, independence: 0, st: -5, rc: 0, ma: -8, bi: -8, sv: -3 },
                        { procedural: 3, substantive: 3, independence: 3, st: 8, rc: 3, ma: 8, bi: 6, sv: 7 },
                        { procedural: 2, substantive: 3, independence: 4, st: 6, rc: 5, ma: 7, bi: 8, sv: 5 },
                        { procedural: 1, substantive: 1, independence: 2, st: -2, rc: 1, ma: 5, bi: 4, sv: -2 }
                    ]
                },
                {
                    titleKey: 'r2_title',
                    briefingKey: 'r2_brief',
                    optionKeys: ['r2_opt1', 'r2_opt2', 'r2_opt3', 'r2_opt4'],
                    scores: [
                        { procedural: 0, substantive: 0, independence: 0, st: -8, rc: -3, ma: -5, bi: -8, sv: -8 },
                        { procedural: 2, substantive: 2, independence: 3, st: 5, rc: 5, ma: 5, bi: 6, sv: 5 },
                        { procedural: 3, substantive: 3, independence: 4, st: 8, rc: 7, ma: 8, bi: 8, sv: 8 },
                        { procedural: 1, substantive: 0, independence: 2, st: -2, rc: 2, ma: 3, bi: 5, sv: -3 }
                    ]
                },
                {
                    titleKey: 'r3_title',
                    briefingKey: 'r3_brief',
                    optionKeys: ['r3_opt1', 'r3_opt2', 'r3_opt3', 'r3_opt4'],
                    scores: [
                        { procedural: 0, substantive: 0, independence: 0, st: -8, rc: -10, ma: -8, bi: -10, sv: -6 },
                        { procedural: 1, substantive: 1, independence: 1, st: -2, rc: -3, ma: -2, bi: -3, sv: -2 },
                        { procedural: 3, substantive: 3, independence: 4, st: 8, rc: 8, ma: 8, bi: 8, sv: 7 },
                        { procedural: 2, substantive: 1, independence: 2, st: 3, rc: 5, ma: 4, bi: 4, sv: 2 }
                    ]
                },
                {
                    titleKey: 'r4_title',
                    briefingKey: 'r4_brief',
                    optionKeys: ['r4_opt1', 'r4_opt2', 'r4_opt3', 'r4_opt4'],
                    scores: [
                        { procedural: 2, substantive: 1, independence: 1, st: -3, rc: 2, ma: -2, bi: -4, sv: -2 },
                        { procedural: 3, substantive: 3, independence: 3, st: 7, rc: 3, ma: 6, bi: 6, sv: 5 },
                        { procedural: 0, substantive: 0, independence: 0, st: -8, rc: -2, ma: -8, bi: -10, sv: -8 },
                        { procedural: 3, substantive: 3, independence: 4, st: 8, rc: 5, ma: 7, bi: 8, sv: 7 }
                    ]
                },
                {
                    titleKey: 'r5_title',
                    briefingKey: 'r5_brief',
                    optionKeys: ['r5_opt1', 'r5_opt2', 'r5_opt3', 'r5_opt4'],
                    scores: [
                        { procedural: 0, substantive: 0, independence: 0, st: -6, rc: -8, ma: -5, bi: -8, sv: -6 },
                        { procedural: 2, substantive: 2, independence: 3, st: 5, rc: 5, ma: 5, bi: 5, sv: 5 },
                        { procedural: 3, substantive: 3, independence: 4, st: 8, rc: 8, ma: 7, bi: 8, sv: 7 },
                        { procedural: 2, substantive: 2, independence: 3, st: 4, rc: 5, ma: 4, bi: 6, sv: 3 }
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    governanceScore: 0,
                    shareholderTrust: 50,
                    regulatoryCompliance: 50,
                    managementAccountability: 50,
                    boardIndependence: 50,
                    stakeholderValue: 50,
                    proceduralTotal: 0,
                    substantiveTotal: 0,
                    independenceTotal: 0,
                    governanceHistory: [],
                    trustHistory: [],
                    regulatoryHistory: [],
                    accountabilityHistory: [],
                    boardIndepHistory: [],
                    valueHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    choice: 0
                };
            }
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._reactBound) {
                // FIX(v1.1.0): the framework's undo restores state but never
                // re-invokes the adapter view; language changes must re-render the
                // localized scenario. Keep the briefing reactive to both.
                this._reactBound = true;
                sim.eventBus.on('period:undone', function(st) { self._updateBriefing(st || sim.state); });
                sim.eventBus.on('language:changed', function() { self._updateBriefing(sim.state); });
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            // FIX(v1.1.0): removed a redundant _updateBriefing() here (it re-labeled
            // the options on every validate/preview). Just read the live selection.
            var selected = document.querySelector('input[name="boardChoice"]:checked');
            if (!selected) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('no_selection_warning'), 'warning'
                );
                return false;
            }
            decisions.choice = parseInt(selected.value);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var optIdx = d.choice - 1;
            var score = round.scores[optIdx];

            var procedural = score.procedural;
            var substantive = score.substantive;
            var independence = score.independence;
            var roundTotal = procedural + substantive + independence;

            state.domainState.proceduralTotal += procedural;
            state.domainState.substantiveTotal += substantive;
            state.domainState.independenceTotal += independence;
            state.domainState.governanceScore += roundTotal * 2;

            state.domainState.shareholderTrust = Math.max(0, Math.min(100, state.domainState.shareholderTrust + score.st));
            state.domainState.regulatoryCompliance = Math.max(0, Math.min(100, state.domainState.regulatoryCompliance + score.rc));
            state.domainState.managementAccountability = Math.max(0, Math.min(100, state.domainState.managementAccountability + score.ma));
            state.domainState.boardIndependence = Math.max(0, Math.min(100, state.domainState.boardIndependence + score.bi));
            state.domainState.stakeholderValue = Math.max(0, Math.min(100, state.domainState.stakeholderValue + score.sv));

            state.domainState.governanceHistory.push(state.domainState.governanceScore);
            state.domainState.trustHistory.push(state.domainState.shareholderTrust);
            state.domainState.regulatoryHistory.push(state.domainState.regulatoryCompliance);
            state.domainState.accountabilityHistory.push(state.domainState.managementAccountability);
            state.domainState.boardIndepHistory.push(state.domainState.boardIndependence);
            state.domainState.valueHistory.push(state.domainState.stakeholderValue);

            var scenarioNames = ['CEO Performance Review', 'Contested Acquisition', 'Whistleblower Complaint', 'CEO Compensation', 'Risk Committee - Market Entry'];

            // FIX(v1.1.0): advance synchronously to the next round. The previous
            // setTimeout closure read state.currentPeriod AFTER the framework had
            // incremented it, so it re-labeled to round N+2 and skipped a scenario.
            // Guard on state identity so the deep-cloned competition preview never
            // mutates the live DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
                var radios = document.querySelectorAll('input[name="boardChoice"]');
                radios.forEach(function(r) { r.checked = false; });
            }

            return {
                period: state.currentPeriod,
                scenario: scenarioNames[roundIdx],
                chosenOption: d.choice,
                procedural: procedural,
                substantive: substantive,
                independence: independence,
                roundScore: roundTotal * 2,
                governanceScore: state.domainState.governanceScore,
                shareholderTrust: state.domainState.shareholderTrust,
                regulatoryCompliance: state.domainState.regulatoryCompliance,
                managementAccountability: state.domainState.managementAccountability,
                boardIndependence: state.domainState.boardIndependence,
                stakeholderValue: state.domainState.stakeholderValue
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('governanceScoreDisplay', 'domainState.governanceScore',
                (v) => Math.round(v).toString());
            uiManager.bind('shareholderTrustDisplay', 'domainState.shareholderTrust',
                (v) => Math.round(v).toString());
            uiManager.bind('regulatoryDisplay', 'domainState.regulatoryCompliance',
                (v) => Math.round(v).toString());
            uiManager.bind('accountabilityDisplay', 'domainState.managementAccountability',
                (v) => Math.round(v).toString());
            uiManager.bind('boardIndepDisplay', 'domainState.boardIndependence',
                (v) => Math.round(v).toString());
            uiManager.bind('valueDisplay', 'domainState.stakeholderValue',
                (v) => Math.round(v).toString());
        }

        getChartConfig() {
            return {
                governanceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Shareholder Trust',
                                data: [],
                                borderColor: '#3498db',
                                backgroundColor: 'rgba(52,152,219,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Regulatory Compliance',
                                data: [],
                                borderColor: '#e74c3c',
                                backgroundColor: 'rgba(231,76,60,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Mgmt Accountability',
                                data: [],
                                borderColor: '#2ecc71',
                                backgroundColor: 'rgba(46,204,113,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Board Independence',
                                data: [],
                                borderColor: '#9b59b6',
                                backgroundColor: 'rgba(155,89,182,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Stakeholder Value',
                                data: [],
                                borderColor: '#f39c12',
                                backgroundColor: 'rgba(243,156,18,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Governance Health Metrics' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: 'Score' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.trustHistory.map(function(_, i) { return 'M' + (i + 1); });
            return {
                governanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.trustHistory },
                        { data: state.domainState.regulatoryHistory },
                        { data: state.domainState.accountabilityHistory },
                        { data: state.domainState.boardIndepHistory },
                        { data: state.domainState.valueHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = 0;
            var procTotal = 0;
            var subTotal = 0;
            var indepTotal = 0;
            history.forEach(function(r) {
                totalScore += (r.results ? r.results.roundScore : 0) || 0;
                procTotal += (r.results ? r.results.procedural : 0) || 0;
                subTotal += (r.results ? r.results.substantive : 0) || 0;
                indepTotal += (r.results ? r.results.independence : 0) || 0;
            });

            var performance = 'Governance Failure';
            if (totalScore >= 85) performance = 'Exceptional Director';
            else if (totalScore >= 70) performance = 'Effective Director';
            else if (totalScore >= 55) performance = 'Developing Director';
            else if (totalScore >= 40) performance = 'Governance Risk';

            var insights = [];
            if (indepTotal >= 16) {
                insights.push('Strong independence: you consistently challenged management when necessary.');
            } else if (indepTotal >= 10) {
                insights.push('Moderate independence: you showed willingness to push back but deferred in some key moments.');
            } else {
                insights.push('Low independence: you tended to defer to management. Effective directors must exercise independent judgment.');
            }
            if (procTotal >= 12) {
                insights.push('Excellent procedural rigor: you followed sound governance processes throughout.');
            } else {
                insights.push('Procedural gaps detected: consider whether you engaged adequate independent advisors and followed proper board process.');
            }
            if (subTotal >= 12) {
                insights.push('Strong substantive judgment across all scenarios.');
            } else {
                insights.push('Review your substantive decisions: some choices may not have optimally balanced monitoring and advisory functions.');
            }

            var lastResult = history[history.length - 1].results || {};
            return {
                totalScore: totalScore,
                proceduralTotal: procTotal,
                substantiveTotal: subTotal,
                independenceTotal: indepTotal,
                performance: performance,
                shareholderTrust: lastResult.shareholderTrust || 50,
                regulatoryCompliance: lastResult.regulatoryCompliance || 50,
                managementAccountability: lastResult.managementAccountability || 50,
                boardIndependence: lastResult.boardIndependence || 50,
                stakeholderValue: lastResult.stakeholderValue || 50,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            if (results.roundScore >= 16) return window.mySimulation.t('hint_excellent');
            if (results.roundScore >= 10) return window.mySimulation.t('hint_good');
            if (results.roundScore >= 4) return window.mySimulation.t('hint_weak');
            return window.mySimulation.t('hint_failure');
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.scenario', label: 'Scenario', i18nKey: 'col_scenario' },
                { key: 'decisions.choice', label: 'Option', i18nKey: 'col_option', formatter: function(v) { return 'Option ' + v; } },
                { key: 'results.procedural', label: 'Procedural', i18nKey: 'col_procedural' },
                { key: 'results.substantive', label: 'Substantive', i18nKey: 'col_substantive' },
                { key: 'results.independence', label: 'Independence', i18nKey: 'col_independence' },
                { key: 'results.roundScore', label: 'Round Score', i18nKey: 'col_round_score' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:                  `Board Effectiveness: Governance in the Boardroom`,
                    subtitle:               `Navigate five critical board scenarios as an independent director`,
                    period_label:           `Board Meeting`,
                    period_of:              `of`,
                    governance_score_label: `Governance Score`,
                    shareholder_trust_label:`Shareholder Trust`,
                    regulatory_label:       `Regulatory Compliance`,
                    accountability_label:   `Mgmt Accountability`,
                    board_indep_label:      `Board Independence`,
                    value_label:            `Stakeholder Value`,
                    decisions_heading:      `Your Decision`,
                    submit_btn:             `Submit Decision`,
                    undo_btn:               `Undo Last Decision`,
                    no_selection_warning:   `Please select one of the options before submitting.`,
                    hint_excellent:         `Excellent governance decision. You demonstrated strong independent judgment and procedural rigor.`,
                    hint_good:              `Good decision. You showed sound governance instincts, though there may have been an even stronger option available.`,
                    hint_weak:              `This decision shows some governance weaknesses. Consider whether you gave management too much deference or skipped procedural steps.`,
                    hint_failure:           `This decision represents a governance failure. Effective directors must challenge management and follow robust processes.`,
                    col_scenario:           `Scenario`,
                    col_option:             `Option`,
                    col_procedural:         `Procedural`,
                    col_substantive:        `Substantive`,
                    col_independence:       `Independence`,
                    col_round_score:        `Round Score`,
                    r1_title:               `Scenario A: CEO Performance Review`,
                    r1_brief:               `The company has missed earnings guidance for two consecutive quarters. The CEO attributes the shortfall to macroeconomic headwinds and an acquisition integration delay. The CFO has privately flagged executive retention risk linked to the CEO management style. A major shareholder is requesting a private meeting with the lead independent director to discuss performance concerns.`,
                    r1_opt1:                `Reaffirm full confidence in the CEO publicly without any additional review process`,
                    r1_opt2:                `Commission a formal performance review with clear Q3 targets and explicit consequences; brief the concerned shareholder on the process underway`,
                    r1_opt3:                `Ask the CFO to formalize concerns in writing; activate succession contingency planning; brief the full board`,
                    r1_opt4:                `Initiate CEO termination discussions immediately`,
                    r2_title:               `Scenario B: The Contested Acquisition`,
                    r2_brief:               `The CEO proposes a $380M acquisition of a regional competitor at a 38% premium to the 90-day average market price. A management-selected investment bank has provided a favorable fairness opinion. The CFO has privately expressed concerns about integration execution risk. Due diligence was compressed due to competitive pressure from other bidders.`,
                    r2_opt1:                `Approve the acquisition based on the management presentation and fairness opinion`,
                    r2_opt2:                `Require an independent fairness opinion from a separate investment bank; request the CFO present a formal risk analysis to the full board`,
                    r2_opt3:                `Commission a 30-day independent review with full due diligence access; require the CFO concerns be formally presented to the full board`,
                    r2_opt4:                `Reject the acquisition without further analysis`,
                    r3_title:               `Scenario C: The Whistleblower Complaint`,
                    r3_brief:               `The audit committee has received a formal written complaint from the Senior Finance Manager alleging that the VP of Revenue Recognition has been recording approximately $12M in revenue before the criteria under IFRS 15 are met. The amount is material enough to change the reported earnings-per-share figure. The CEO has been briefed and expresses confidence this is a misunderstanding of legitimate accounting policies.`,
                    r3_opt1:                `Accept the CEO explanation; ask the CFO to review the accounting treatment; close the matter`,
                    r3_opt2:                `Instruct external auditors to review the revenue recognition policy and confirm compliance`,
                    r3_opt3:                `Engage independent legal counsel and forensic accountants reporting directly to the audit committee; suspend the revenue in question pending investigation; protect the complainant from retaliation`,
                    r3_opt4:                `Immediately disclose the investigation to regulators and halt trading`,
                    r4_title:               `Scenario D: Compensation Committee - CEO Pay Decision`,
                    r4_brief:               `The CEO long-term incentive plan is maturing. The company achieved 14.5% EPS CAGR versus a 20% maximum target and 10% threshold, yielding a formulaic payout of 72% of maximum (~$6.4M). However, the peer group averaged 17% EPS CAGR, and a weaker currency partly inflated reported results. Major institutional shareholders have signaled they will vote against the remuneration report at the upcoming AGM.`,
                    r4_opt1:                `Pay the 72% formulaic result and proceed to the AGM vote as planned`,
                    r4_opt2:                `Apply downward discretion to reduce payout to 50%; communicate the rationale to shareholders before the AGM`,
                    r4_opt3:                `Apply upward discretion to increase payout to 90% based on absolute performance`,
                    r4_opt4:                `Engage directly with the top 10 institutional shareholders before the AGM to explain the compensation rationale and planned downward adjustments`,
                    r5_title:               `Scenario E: Risk Committee - High-Risk Market Entry`,
                    r5_brief:               `The CEO proposes entering the Argentine market by acquiring a local distribution company. The ERM framework rates the deal as high-risk on three dimensions: currency risk, regulatory risk from exchange controls, and counterparty risk from unresolved related-party transactions in the target. The Risk Appetite Statement classifies Argentina as a monitored market requiring enhanced due diligence. The CEO argues the opportunity window is time-limited following favorable reform conditions.`,
                    r5_opt1:                `Approve the acquisition as recommended, accepting the ERM risk rating`,
                    r5_opt2:                `Require contractual protections mitigating the three identified risk dimensions before granting approval`,
                    r5_opt3:                `Require a formal risk appetite amendment approved by the full board before proceeding with the transaction`,
                    r5_opt4:                `Reject the transaction on risk grounds without further analysis`
                },
                es: {
                    title:                  `Efectividad del Directorio: Gobernanza Corporativa`,
                    subtitle:               `Navega cinco escenarios de directorio como director independiente`,
                    period_label:           `Junta de Directorio`,
                    period_of:              `de`,
                    governance_score_label: `Puntaje de Gobernanza`,
                    shareholder_trust_label:`Confianza del Accionista`,
                    regulatory_label:       `Cumplimiento Regulatorio`,
                    accountability_label:   `Rendición de Cuentas`,
                    board_indep_label:      `Independencia del Directorio`,
